import React, { useState } from 'react';
// Agar aap images local folder mein rakhte hain:
// import bikeImage from './images/bike_graphic.png';
// import tataAceImage from './images/tata_ace_graphic.png';
// import pickupImage from './images/pickup_graphic.png';

import axios from 'axios';
import { useNavigate } from 'react-router-dom';
import './BookingForm.css';

const BookingForm = () => {
    const navigate = useNavigate();
    const [loading, setLoading] = useState(false);
    
    // Form data mein abhi direct vehicle selection nahi hai, use alag state se handle karenge submit pe.
    const [formData, setFormData] = useState({
        senderName: '',
        senderPhone: '',
        sourceAddress: '',
        destinationAddress: '',
        weight: '',
        distanceKm: ''
    });

    const [selectedVehicle, setSelectedVehicle] = useState('bike'); // Default selection

    // Vehicle details is card UI ko match karne ke liye
    const vehicleOptions = [
        {
            id: 'bike',
            title: 'Two-Wheeler (Bike)',
            description: 'Quick & Small (Upto 20kg)',
            baseFare: 40,
            // image: bikeImage, // Agar local file use kar rahe hain
            image: "assests/image1.jpg", // Temporarily path
        },
        {
            id: 'tata ace',
            title: 'Tata Ace (Mini Truck)',
            description: 'Heavy Loads (750kg)',
            baseFare: 250,
            // image: tataAceImage,
            image: "https://your-public-cdn-link.com/images/tata_ace_graphic.png", 
        },
        {
            id: 'pickup 8ft',
            title: 'Pickup 8ft',
            description: 'Large Items (1.5 Tons)',
            baseFare: 450,
            // image: pickupImage,
            image: "https://your-public-cdn-link.com/images/pickup_graphic.png",
        }
    ];

    const handleChange = (e) => {
        const { name, value } = e.target;
        const finalValue = (name === 'weight' || name === 'distanceKm') ? parseFloat(value) : value;
        setFormData({ ...formData, [name]: finalValue });
    };

    const handleVehicleSelect = (id) => {
        setSelectedVehicle(id);
    };

    const handleSubmit = async (e) => {
        e.preventDefault();
        setLoading(true);

        // Vehicle details backend ke liye prepare karna
        const submissionData = {
            ...formData,
            vehicleType: selectedVehicle,
            // Backend ko base fare bhi send kar sakte hain agar pricing logic server pe nahi hai:
            // estimatedBaseFare: vehicleOptions.find(v => v.id === selectedVehicle).baseFare
        };

        try {
            const res = await axios.post("http://localhost:9023/api/parcels/book", submissionData);
            if (res.data && res.data.trackingId) {
                alert(`Booking Successful! Tracking ID: ${res.data.trackingId}`);
                navigate('/track'); 
            }
        } catch (error) {
            console.error("Error booking parcel:", error);
            alert("Booking failed. Please check if Backend is running.");
        } finally {
            setLoading(false);
        }
    };

    return (
        <div className="booking-form-main-container">
            <div className="booking-content-area">
                
                {/* Section 1: Vehicle Selection (Isi par focus hai) */}
                <div className="section-container">
                    <h2 className="section-title">Choose Your Vehicle</h2>
                    
                    <div className="vehicle-selection-grid">
                        {vehicleOptions.map((vehicle) => (
                            <div 
                                key={vehicle.id}
                                className={`vehicle-option-card ${selectedVehicle === vehicle.id ? 'active-card' : ''}`}
                                onClick={() => handleVehicleSelect(vehicle.id)}
                            >
                                {/* Selected State Dot */}
                                <div className="card-selection-indicator">
                                    <div className={`selection-dot ${selectedVehicle === vehicle.id ? 'dot-active' : ''}`}></div>
                                </div>
                                
                                {/* Graphical Image */}
                                <img src={vehicle.image} alt={vehicle.title} className="vehicle-graphic-img" />
                                
                                {/* Text Content */}
                                <div className="vehicle-card-details">
                                    <p className="vehicle-card-title">{vehicle.title}</p>
                                    <p className="vehicle-card-desc">{vehicle.description}</p>
                                    <p className="vehicle-card-fare">Estimated Base Fare: ₹{vehicle.baseFare}</p>
                                </div>
                            </div>
                        ))}
                    </div>
                </div>

                {/* Section 2: Rest of the Form */}
                <form onSubmit={handleSubmit} className="booking-details-form">
                    <h2 className="section-title">Enter Parcel Details</h2>
                    
                    <div className="input-group-row">
                        <input type="text" name="senderName" placeholder="Full Name" onChange={handleChange} required />
                        <input type="text" name="senderPhone" placeholder="Phone Number" onChange={handleChange} required />
                    </div>

                    <div className="input-group-row-single">
                        <input type="text" name="sourceAddress" placeholder="Pickup Address (From)" onChange={handleChange} required />
                        <input type="text" name="destinationAddress" placeholder="Drop Address (To)" onChange={handleChange} required />
                    </div>

                    <div className="input-group-row">
                        <input type="number" name="distanceKm" placeholder="Distance (km)" onChange={handleChange} required />
                        <input type="number" name="weight" placeholder="Weight (kg)" onChange={handleChange} required />
                    </div>

                    <button type="submit" className="confirm-booking-btn" disabled={loading}>
                        {loading ? 'Processing...' : 'Confirm Booking'}
                    </button>
                </form>

            </div>
        </div>
    );
};

export default BookingForm;
